class Solution {
public:
    int countDays(int days, vector<vector<int>>& meetings) {
        sort(meetings.begin(), meetings.end());
        int occupied = 0;
        int cur_s = meetings[0][0], cur_e = meetings[0][1];
        for (size_t i = 1; i < meetings.size(); ++i) {
            int s = meetings[i][0], e = meetings[i][1];
            if (s <= cur_e) {
                cur_e = max(cur_e, e);
            } else {
                occupied += cur_e - cur_s + 1;
                cur_s = s;
                cur_e = e;
            }
        }
        occupied += cur_e - cur_s + 1;
        return days - occupied;
    }
};

class Solution {
    public int countDays(int days, int[][] meetings) {
        Arrays.sort(meetings, (a, b) -> Integer.compare(a[0], b[0]));
        int occupied = 0;
        int curS = meetings[0][0], curE = meetings[0][1];
        for (int i = 1; i < meetings.length; ++i) {
            int s = meetings[i][0], e = meetings[i][1];
            if (s <= curE) {
                curE = Math.max(curE, e);
            } else {
                occupied += curE - curS + 1;
                curS = s;
                curE = e;
            }
        }
        occupied += curE - curS + 1;
        return days - occupied;
    }
}

var countDays = function(days, meetings) {
    meetings.sort((a, b) => a[0] - b[0]);
    let occupied = 0;
    let curS = meetings[0][0], curE = meetings[0][1];
    for (let i = 1; i < meetings.length; ++i) {
        const s = meetings[i][0], e = meetings[i][1];
        if (s <= curE) {
            curE = Math.max(curE, e);
        } else {
            occupied += curE - curS + 1;
            curS = s;
            curE = e;
        }
    }
    occupied += curE - curS + 1;
    return days - occupied;
};
